  feed.emit('next');
  assert.deepEqual(recorded.map(x => x.frame), ['cached', 'next']);
  assert.deepEqual(shown.map(x => x.frame), ['cached', 'next']);
}

{
  const deferred = new Map(), recorded = [], shown = [];
  const feed = createProgressFeed({ decode(packet) {
    return new Promise(resolve => deferred.set(packet, resolve));
  }});
  const workspace = createTransferWorkspace({
    transport() {}, onCancel() {}, record() {}, showQueued() {},
    recordProgress: entry => recorded.push(entry), showProgress: entry => shown.push(entry),
  });
