  feed.emit('newer');
  deferred.get('newer')('newer');
  await Promise.resolve();
  deferred.get('older')('older');
  await Promise.resolve();
  assert.deepEqual(recorded.map(x => x.frame), ['newer', 'older']);
  assert.deepEqual(shown.map(x => x.frame), ['newer']);
}

{
